import{z as B,x as p,o as E,c as h,q as r,j as i,D as t,d as s,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"摊还分析","description":"","frontmatter":{"title":"摊还分析","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/amortized-analysis.md","filePath":"cs/amortized-analysis.md","lastUpdated":1791413859000}'),A={name:"cs/amortized-analysis.md"};function d(m,a,T,C,u,D){const n=p("Mermaid");return E(),h("div",null,[a[2]||(a[2]=r('<h1 id="摊还分析" tabindex="-1">摊还分析 <a class="header-anchor" href="#摊还分析" aria-label="Permalink to &quot;摊还分析&quot;">​</a></h1><div class="epigraph"><p>最坏单次可以很贵，只要贵的次数被足够多次便宜操作摊平；表的倍增复制就是这一笔账。</p><footer>—— 据 Tarjan, Amortized Computational Complexity, SIAM J. Algebraic Discrete Methods 1985；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/ring-buffer">上一课</a>和<a href="/cs/array-random-access">数组与随机访问</a>都避开了「满了怎么办」。动态数组在容量用尽时分配两倍空间并复制，单次 \\(\\Theta(n)\\)，看起来破坏了 \\(\\Theta(1)\\) 合同。<a href="/cs/asymptotic-notation">渐近记号</a>给的是单次或最坏。本课不重讲 FIFO。缺口是：对一串操作求和再除次数，让偶发的线性复制不影响平均每操作 \\(\\Theta(1)\\)。本课只钉摊还，方法用合计与势能，不把核函数摊还写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若合同写成「每次 push 最坏 \\(\\Theta(1)\\)」，倍增数组是撒谎。若写成「每次最坏 \\(\\Theta(n)\\)」，又掩盖了 \\(n\\) 次 push 总共 \\(\\Theta(n)\\) 的事实。缺口不是新的表示，而是第三种代价声明：<strong>摊还 \\(\\Theta(1)\\)</strong>——任意 \\(m\\) 次操作总时间 \\(\\Theta(m)\\)，因而平均每次 \\(\\Theta(1)\\)，但单次可以是线性。</p><p>最坏仍然存在：实时路径若不能容忍那一次复制，应预分配或用链表。摊还不是消灭峰值。</p><p><span class="marginnote">直觉类比：摊还账像高速公路的 ETC 月结——单看某一次过闸（那一拍复制）扣了一大笔，吓人；把整月账单除以过闸次数，每次成本恒定。摊还界承诺的是「月账单 / 次数」这一档，从不承诺每次过闸都小额。</span></p><p><span class="marginnote">势能法把「已分配而尚未用的空槽」当成储蓄。复制时把储蓄花掉，不让总账变负。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>合计：从空表倍增到 \\(n\\)，复制长度 \\(1+2+\\cdots+n/2 \\lt n\\)，全部 push 的插入本身也是 \\(n\\)，总和 \\(\\Theta(n)\\)。势能 \\(\\Phi\\)：取 \\(\\Phi=\\) 当前长度与容量之差的常数倍，使每次便宜操作 \\(\\hat{c}=c+\\Delta\\Phi=O(1)\\)，复制时 \\(\\Delta\\Phi\\) 为负、抵消 \\(\\Theta(n)\\)。</p><p><span class="marginnote">数字实例：从容量 1 开始连 push 9 个元素，容量在 1、2、4、8 处翻倍，累计搬动 \\(1+2+4+8=15\\) 次，加上 9 次普通写入，总代价不到 24 次基本操作——平均每次 push 摊不到 3 步，且这个常数与 \\(n\\) 无关，这就是摊还 \\(\\Theta(1)\\) 的实感。</span></p>',11)),(E(),i(o,null,{default:t(()=>[l(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUSH%5B%22%E6%99%AE%E9%80%9A%20push%20%CE%98(1)%22%5D%20--%3E%20AM%5B%22%E6%91%8A%E8%BF%98%20%CE%98(1)%22%5D%0A%20%20GROW%5B%22%E5%80%8D%E5%A2%9E%E5%A4%8D%E5%88%B6%20%CE%98(n)%22%5D%20--%3E%20AM%0A%20%20AM%20--%3E%20SUM%5B%22m%20%E6%AC%A1%E6%80%BB%20%CE%98(m)%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"收缩可对称地减半，须避免在阈值附近振荡；细节是实现，本课要求总账仍线性。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"有了摊还，动态数组可以进入栈与队列的合同：无界、摊还 \\(\\Theta(1)\\) 端操作。后课散列的再散列、并查集的路径压缩，同一套语言。二叉树平衡的单次旋转仍是最坏 \\(\\Theta(1)\\)，不需要摊还；伸展树才靠摊还。",-1)),a[6]||(a[6]=e("p",null,"容量翻倍的那一下在时间轴上怎么发生、账怎么平？看这个循环：",-1)),(E(),i(o,null,{default:t(()=>[l(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%AE%B9%E9%87%8F%E6%8C%89%201%20%E2%86%92%202%20%E2%86%92%204%20%E2%86%92%208%20%E9%80%90%E6%A1%A3%E7%BF%BB%E5%80%8D%22%5D%20--%3E%20B%7B%22%E5%BD%93%E5%89%8D%E5%B1%82%E8%BF%98%E6%9C%89%E7%A9%BA%E6%A7%BD%E5%90%97%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E6%9C%89%22%7C%20C%5B%22%E4%BE%BF%E5%AE%9C%20push%EF%BC%9A%CE%98(1)%EF%BC%8C%E9%A1%BA%E5%B8%A6%E7%BB%99%E5%8A%BF%E8%83%BD%E8%B4%A6%E6%88%B7%E5%AD%98%E4%B8%80%E7%82%B9%22%5D%0A%20%20C%20--%3E%20B%0A%20%20B%20--%3E%7C%22%E6%BB%A1%E4%BA%86%22%7C%20D%5B%22%E8%BF%99%E4%B8%80%E6%AC%A1%E8%B4%B5%EF%BC%9A%E6%95%B4%E8%A1%A8%E5%A4%8D%E5%88%B6%20%CE%98(n)%EF%BC%8C%E4%BB%8E%E8%B4%A6%E6%88%B7%E5%8F%96%E9%92%B1%E4%BB%98%E8%B4%A6%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%AE%B9%E9%87%8F%E7%BF%BB%E5%80%8D%EF%BC%8C%E5%9B%9E%E5%88%B0%E4%BE%BF%E5%AE%9C%E5%8C%BA%E9%97%B4%E7%BB%A7%E7%BB%AD%20push%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">常见误区：初学者把「摊还 \\(\\Theta(1)\\)」读成「每次都 \\(\\Theta(1)\\)」。实际上那次 \\(\\Theta(n)\\) 的复制真实发生、真实可测：音频回调、硬实时循环里一次抖动就超标。此类场景要么开工前预分配好容量，要么改用不摊还的结构——摊还合同救不了对单次延迟敏感的路径。</span></p><p>摊还不假设概率。期望分析（随机散列、随机快排）是另一张账单，后课会分开写。势能必须对空结构取零（或非负），否则合计会偷一项常数债。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明所有 ADT 都有摊还界。也不把摊还与并行加速比混谈。缓存缺失的摊还（扫描的强制缺失）可以类比，但存储器层次仍用命中率说话。</p><p>后课默认：动态表 push 摊还 \\(\\Theta(1)\\)。查找按键而不是按下标，需要有序树：下一课 BST。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>摊还描述一串操作的平均，允许峰值。</li><li>倍增数组：\\(m\\) 次 push 总 \\(\\Theta(m)\\)。</li><li>有序字典的树表示是下一课，最坏先按高度算。</li><li>摊还不是期望：没有随机假设，实时路径仍可能碰到那一次 \\(\\Theta(n)\\)。</li><li>出处：Tarjan, 1985；Cormen et al. 第 17 章。</li></ul>',7))])}const _=B(A,[["render",d]]);export{f as __pageData,_ as default};
